import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { BrowserRouter as Router, Routes, Route, Link, useLocation, useNavigate } from 'react-router-dom';

// --- NAVBAR ---
const Navbar = ({ cartCount }) => {
  const location = useLocation();
  const isActive = (path) => location.pathname === path;
  const user = localStorage.getItem('username');

  const handleLogout = () => {
    localStorage.clear();
    window.location.href = "/login";
  };

  return (
    <nav className="bg-white/95 backdrop-blur-md sticky top-0 z-50 w-full border-b border-gray-100 shadow-sm">
      <div className="max-w-7xl mx-auto px-6 h-20 flex justify-between items-center">
        <Link to="/" className="flex items-center space-x-3">
          <div className="bg-orange-600 p-2 rounded-full shadow-md">
            <svg width="24" height="24" viewBox="0 0 512 512" fill="white"><path d="M416 0c-35.3 0-64 28.7-64 64V288c0 17.7 14.3 32 32 32h32V480c0 17.7 14.3 32 32 32s32-14.3 32-32V32C480 14.3 465.7 0 448 0H416zM80 0C44.7 0 16 28.7 16 64V224c0 35.3 28.7 64 64 64h16V480c0 17.7 14.3 32 32 32s32-14.3 32-32V288h16c35.3 0 64-28.7 64-64V64c0-35.3-28.7-64-64-64H80z"/></svg>
          </div>
          <span className="font-black text-xl tracking-tighter text-gray-900 uppercase italic">Fast<span className="text-orange-600">Délice</span></span>
        </Link>
        <div className="hidden md:flex space-x-8 text-[12px] font-black uppercase text-gray-800">
          {[{ name: 'Accueil', path: '/' }, { name: 'Menu', path: '/menu' }, { name: 'À Propos', path: '/about' }, { name: 'Contact', path: '/contact' }].map((link) => (
            <Link key={link.path} to={link.path} className={`relative pb-1 transition-all ${isActive(link.path) ? 'text-orange-600 border-b-2 border-orange-600' : 'hover:text-orange-600'}`}>
              {link.name}
            </Link>
          ))}
        </div>
        <div className="flex items-center space-x-4">
          <Link to="/panier" className="relative flex items-center space-x-2 text-gray-800">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 3h2l.4 2M7 13h10l4-8H5.4M7 13L5.4 5M7 13l-2.293 2.293c-.63.63-.184 1.707.707 1.707H17m0 0a2 2 0 100 4 2 2 0 000-4zm-8 2a2 2 0 11-4 0 2 2 0 014 0z" /></svg>
            <span className="bg-orange-600 text-white text-[10px] font-bold rounded-full h-5 w-5 flex items-center justify-center">{cartCount}</span>
          </Link>
          {user ? (
            <div className="flex items-center space-x-4">
              <span className="text-[11px] font-black uppercase text-orange-600 italic border-b-2 border-orange-600">Salut, {user}</span>
              <button onClick={handleLogout} className="text-red-600 text-[10px] font-black uppercase hover:underline">Quitter</button>
            </div>
          ) : (
            <Link to="/login" className="bg-orange-600 text-white px-5 py-2.5 rounded-full text-[11px] font-black uppercase tracking-widest hover:bg-gray-900 transition">Connexion</Link>
          )}
        </div>
      </div>
    </nav>
  );
};

// --- HOME PAGE (With fixed section placement) ---
const Home = () => (
  <div className="min-h-screen">
    {/* Hero Section with Pizza Background */}
    <div className="relative h-[90vh] flex items-center justify-center overflow-hidden">
      <div className="absolute inset-0 z-0">
        <img src="https://images.unsplash.com/photo-1513104890138-7c749659a591?q=80&w=2070" className="w-full h-full object-cover" alt="pizza-bg" />
        <div className="absolute inset-0 bg-black/50"></div>
      </div>
      <div className="relative z-10 text-center">
        <h1 className="text-7xl md:text-9xl font-black text-white mb-6 tracking-tighter italic">Fast<span className="text-orange-600">Délice</span></h1>
        <p className="text-xl text-white mb-12 font-bold italic opacity-90">"La passion du goût, l'élégance du service."</p>
        <Link to="/menu" className="bg-orange-600 text-white px-14 py-5 rounded-full font-black uppercase text-sm tracking-widest hover:bg-white hover:text-orange-600 transition shadow-2xl">
          Commander Maintenant
        </Link>
      </div>
    </div>

    {/* Testimonials Section (Below Hero - White Background) */}
    <div className="bg-white py-24 px-6">
      <div className="max-w-7xl mx-auto text-center">
        <h2 className="text-3xl md:text-4xl font-black text-gray-900 italic uppercase mb-16">
          Ce que nos clients disent
        </h2>
        <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
          {[
            { n: "SARAH B.", t: "La meilleure pizza que j'ai mangée à Fès!", s: "★★★★★" },
            { n: "AHMED L.", t: "Livraison rapide et plats chauds. Top!", s: "★★★★★" },
            { n: "YOUSSEF M.", t: "Qualité exceptionnelle pour le prix.", s: "★★★★" }
          ].map((v, i) => (
            <div key={i} className="bg-gray-50 p-10 rounded-[2.5rem] border border-gray-100 flex flex-col items-center shadow-sm">
              <div className="text-orange-500 mb-4 text-xs font-bold">{v.s}</div>
              <p className="text-gray-700 italic font-medium mb-8 text-lg">"{v.t}"</p>
              <span className="text-[10px] font-black text-gray-900 uppercase tracking-widest mt-auto">
                — {v.n}
              </span>
            </div>
          ))}
        </div>
